{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In humans, [123/124/131I]AM281, a close pyrazole-carboxamide analogue sharing the dichlorophenyl and hydrazide core with the query, met the criterion of ready permeation across the blood-brain barrier and enabled CB1 quantification, directly supporting CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Ex vivo autoradiography in rats after intravenous [123I]AM281 showed high brain radioactivity in CB1-rich regions, demonstrating direct brain penetration of the same pyrazole-carboxamide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "GNE-0723 showed excellent brain penetration with similar unbound plasma and brain concentrations and no active efflux after oral dosing in mice, indicating that lipophilic heteroaromatic compounds in this evidence set can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Compound 71, a brain-penetrant PDE2A inhibitor, gave a rat CSF/Cbu ratio of 0.87, supporting meaningful CNS exposure for structurally related lipophilic heteroaromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Flurazepam rapidly entered CSF with a peak concentration of 44 ng/mL at 5 min, demonstrating that lipophilic neutral compounds can achieve rapid CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Pass: the closest high-transfer analogue AM281 is directly brain-permeable in rats and humans, and multiple lipophilic heteroaromatic CNS ligands in the evidence set show meaningful brain/CSF exposure; this transferable experimental evidence overrides the uncertain physicochemical prior.",
  "evidence_gaps": [
    "No direct brain/plasma/CSF measurement for the exact query molecule; prediction relies on close analogue AM281 and other lipophilic CNS penetrants.",
    "High molecular weight (~618 Da) and very high logP (~8) may increase plasma protein binding and efflux; these liabilities were not directly measured for the query.",
    "Potential P-gp/BCRP efflux and hydrazide metabolic stability of the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

